'use client';

import {
  Calendar,
  Settings2,
  Sun,
  Moon,
  Wallet,
  Pencil,
  Plus,
  X,
  Check,
  Sparkles,
  Trash2,
  Utensils,
  Bus,
  PencilRuler,
  Smartphone,
  PartyPopper,
  Shapes,
  Send,
  LucideProps,
} from 'lucide-react';

const iconMap: Record<string, React.ComponentType<LucideProps>> = {
  calendar: Calendar,
  'settings-2': Settings2,
  sun: Sun,
  moon: Moon,
  wallet: Wallet,
  pencil: Pencil,
  plus: Plus,
  x: X,
  check: Check,
  sparkles: Sparkles,
  'trash-2': Trash2,
  utensils: Utensils,
  bus: Bus,
  'pencil-ruler': PencilRuler,
  smartphone: Smartphone,
  'party-popper': PartyPopper,
  shapes: Shapes,
  send: Send,
};

interface IconProps extends LucideProps {
  name: string;
}

export default function Icon({ name, ...props }: IconProps) {
  const Component = iconMap[name];
  if (!Component) return null;
  return <Component {...props} />;
}
